package com.performance.reflection;

import java.lang.invoke.MethodHandle;
import java.lang.invoke.MethodHandles;
import java.lang.invoke.MethodType;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class ReflectionOptimizer {

    // Cache reflective targets to avoid the massive overhead of Class.getMethod() lookups
    private static final Map<String, Method> METHOD_CACHE = new ConcurrentHashMap<>();
    private static MethodHandle cachedHandle;

    public static class TargetComponent {
        private String secureToken = "INITIAL_STATE";

        private void updateToken(String newToken) {
            this.secureToken = newToken;
        }
    }

    public static void main(String[] args) throws Throwable {
        TargetComponent instance = new TargetComponent();

        // 1. Dynamic Instantiation via Constructor
        Constructor<TargetComponent> constructor = TargetComponent.class.getDeclaredConstructor();
        constructor.setAccessible(true); // Bypass private access modifier
        TargetComponent newInstance = constructor.newInstance();

        // 2. Optimized Field Access (Bypassing encapsulation)
        Field tokenField = TargetComponent.class.getDeclaredField("secureToken");
        tokenField.setAccessible(true);
        String value = (String) tokenField.get(instance);
        System.out.println("Retrieved Field Value: " + value);

        // 3. Cached Method Invocation (Mitigating lookup cost)
        Method method = METHOD_CACHE.computeIfAbsent("updateToken", key -> {
            try {
                Method m = TargetComponent.class.getDeclaredMethod("updateToken", String.class);
                m.setAccessible(true);
                return m;
            } catch (NoSuchMethodException e) {
                throw new RuntimeException(e);
            }
        });
        method.invoke(instance, "UPDATED_VIA_REFLECTION");

        // 4. Modern Alternative: MethodHandles (Highly optimized by JIT if static final)
        MethodHandles.Lookup lookup = MethodHandles.privateLookupIn(TargetComponent.class, MethodHandles.lookup());
        cachedHandle = lookup.findVirtual(TargetComponent.class, "updateToken", MethodType.methodType(void.class, String.class));
        cachedHandle.invokeExact(instance, "UPDATED_VIA_METHOD_HANDLE");
    }
}
